const IMGS = "data:image/png;base64,";

const happy1 = "assets/img/avatars/happy.png";
const cheer = "assets/img/avatars/cheer.png";
const confident = "assets/img/avatars/confident.png";
const excited = "assets/img/avatars/excited.png";
const idea = "assets/img/avatars/idea.png";
const love = "assets/img/avatars/love.png";
const relax = "assets/img/avatars/relax.png";
const surprise = "assets/img/avatars/surprise.png";
const think = "assets/img/avatars/think.png";


const pet = document.getElementById('pet'),
      flip = pet.querySelector('.flip'),
      spr = pet.querySelector('.sprite'),
      bub = document.getElementById('bubble');
const W = 120;
const sleep = ms => new Promise(r => setTimeout(r, ms));

/* ---------- colours taken from the character ---------- */
const O='#4a3328', SK='#EBB57F', HAIR='#3d2d24', SW='#8e2f4d', PT='#a97c50', SH='#3a2b25', BD='#5c4b3d', RED='#d6283a';
const ST = `stroke="${O}" stroke-width="2.5" stroke-linejoin="round" stroke-linecap="round"`;

/* ---------- SVG character builder (different poses) ---------- */
function eyes(t, br){
  const L=47, R=73, y=58;
  const open=(rx,ry)=>[L,R].map(x=>`<ellipse cx="${x}" cy="${y}" rx="${rx}" ry="${ry}" fill="#1b1210"/><circle cx="${x+2}" cy="${y-2}" r="${rx/3}" fill="#fff"/>`).join('');
  const spiral=x=>`<path class="spin" d="M${x} ${y} m-1 0 a2 2 0 1 1 2 2 a4 4 0 1 1 -4 -4 a6 6 0 1 1 6 6" fill="none" stroke="#1b1210" stroke-width="2" stroke-linecap="round"/>`;
  let e='';
  if(t==='open') e=open(4,5.5);
  if(t==='wide') e=open(5.5,7.5);
  if(t==='happy') e=[L,R].map(x=>`<path d="M${x-5} ${y+2} q5 -7 10 0" fill="none" stroke="#1b1210" stroke-width="3" stroke-linecap="round"/>`).join('');
  if(t==='sleepy') e=[L,R].map(x=>`<path d="M${x-5} ${y} q5 5 10 0" fill="none" stroke="#1b1210" stroke-width="3" stroke-linecap="round"/>`).join('');
  if(t==='x') e=[L,R].map(x=>`<path d="M${x-4} ${y-4} l8 8 m0 -8 l-8 8" stroke="#1b1210" stroke-width="3" stroke-linecap="round"/>`).join('');
  if(t==='dizzy') e=spiral(L)+spiral(R);
  const brow=[L,R].map(x=>`<path d="M${x-7} ${40+br} q7 -5 14 0" fill="none" stroke="${HAIR}" stroke-width="3" stroke-linecap="round"/>`).join('');
  return e+brow;
}
function mouth(t){
  if(t==='smile') return `<path d="M51 75 q9 10 18 0 z" fill="${RED}" ${ST}/>`;
  if(t==='open')  return `<path d="M49 73 q11 18 22 0 z" fill="${RED}" ${ST}/><path d="M54 82 q6 4 12 0 q-6 -3 -12 0" fill="#ff8a8a"/>`;
  if(t==='scream')return `<ellipse cx="60" cy="80" rx="7" ry="9" fill="#8a1424" ${ST}/>`;
  if(t==='wavy')  return `<path d="M50 78 q5 -5 10 0 t10 0" fill="none" stroke="#1b1210" stroke-width="3" stroke-linecap="round"/>`;
  if(t==='o')     return `<ellipse cx="60" cy="78" rx="4" ry="5" fill="#8a1424" ${ST}/>`;
  return '';
}
function arm(x,a){return `<g transform="rotate(${a} ${x} 96)"><rect x="${x-7}" y="90" width="14" height="36" rx="7" fill="${SW}" ${ST}/><circle cx="${x}" cy="129" r="7" fill="${SK}" ${ST}/></g>`}
function leg(x,a){return `<g transform="rotate(${a} ${x} 130)"><rect x="${x-8}" y="126" width="16" height="32" rx="7" fill="${PT}" ${ST}/><ellipse cx="${x}" cy="160" rx="11" ry="6" fill="${SH}" ${ST}/></g>`}
function char(o){
  o=Object.assign({la:0,ra:0,ll:0,rl:0,e:'open',m:'smile',br:0,stars:false},o);
  const hair=[[30,36],[42,25],[57,21],[72,23],[86,30],[93,43],[27,50],[94,56]].map(([x,y])=>`<circle cx="${x}" cy="${y}" r="14" fill="${HAIR}" ${ST}/>`).join('');
  return `<svg viewBox="0 0 120 170" xmlns="http://www.w3.org/2000/svg">
    ${leg(50,o.ll)}${leg(70,o.rl)}
    <rect x="40" y="122" width="40" height="16" rx="6" fill="${PT}" ${ST}/>
    <rect x="32" y="86" width="56" height="46" rx="18" fill="${SW}" ${ST}/>
    ${arm(34,o.la)}${arm(86,o.ra)}
    <g class="head">
      ${hair}
      <circle cx="26" cy="64" r="6" fill="${SK}" ${ST}/><circle cx="94" cy="64" r="6" fill="${SK}" ${ST}/>
      <circle cx="60" cy="60" r="34" fill="${SK}" ${ST}/>
      <path d="M27 62 Q30 100 60 100 Q90 100 93 62 Q88 76 76 71 Q60 67 44 71 Q32 76 27 62Z" fill="${BD}" ${ST}/>
      <path d="M28 48 Q38 26 60 28 Q84 26 92 48 Q76 38 60 40 Q44 38 28 48Z" fill="${HAIR}" ${ST}/>
      <circle cx="38" cy="70" r="5" fill="#ff8fa0" opacity=".7"/><circle cx="82" cy="70" r="5" fill="#ff8fa0" opacity=".7"/>
      <circle cx="47" cy="58" r="13" fill="#fff" fill-opacity=".25" stroke="${O}" stroke-width="2.5"/>
      <circle cx="73" cy="58" r="13" fill="#fff" fill-opacity=".25" stroke="${O}" stroke-width="2.5"/>
      <path d="M60 57 h0" stroke="${O}" stroke-width="2.5"/>
      ${eyes(o.e,o.br)}${mouth(o.m)}
    </g>
    ${o.stars?`<g class="stars" font-size="14" fill="#ffc21a" stroke="${O}" stroke-width=".6"><text x="22" y="14">★</text><text x="90" y="14">★</text><text x="56" y="0">★</text></g>`:''}
  </svg>`;
}

/* ---------- poses / scenes ---------- */
const POSE = {
  fall:    ()=>char({la:155,ra:-155,ll:14,rl:-20,e:'wide',m:'scream',br:-3}),
  lying:   ()=>char({la:20,ra:-20,ll:6,rl:-6,e:'x',m:'wavy'}),
  dizzy:   ()=>char({la:30,ra:-30,ll:8,rl:-8,e:'dizzy',m:'wavy',stars:true}),
  nod:     ()=>char({e:'happy',m:'smile'}),
  stand:   ()=>char({la:6,ra:-6,e:'open',m:'smile'}),
  walkA:   ()=>char({la:28,ra:-28,ll:-24,rl:24,e:'open',m:'smile'}),
  walkB:   ()=>char({la:-28,ra:28,ll:24,rl:-24,e:'open',m:'smile'}),
  excited: ()=>`<img src="${IMGS}" alt="excited">`,
  happy: ()=>`<img src="${happy1}" alt="happy">`,
  happy1: ()=>`<img src="${love}" alt="love">`,
  cheer: ()=>`<img src="${cheer}" alt="cheer">`,
  relax: ()=>`<img src="${relax}" alt="relax">`,
  confident: ()=>`<img src="${confident}" alt="confident">`,
  idea: ()=>`<img src="${idea}" alt="idea">`,
  surprise: ()=>`<img src="${surprise}" alt="surprise">`,
  think: ()=>`<img src="${think}" alt="think">`
};
function show(pose, cls=''){ spr.className='sprite '+cls; spr.innerHTML=POSE[pose](); }

/* ---------- message bubble ---------- */
function say(html){
  bub.innerHTML=html; bub.style.display='block'; bub.style.marginLeft='0';
  const r=bub.getBoundingClientRect(), pad=8;                 // keep inside the screen
  if(r.left<pad) bub.style.marginLeft=(pad-r.left)+'px';
  else if(r.right>innerWidth-pad) bub.style.marginLeft=(innerWidth-pad-r.right)+'px';
}
const hideBubble=()=>{bub.style.display='none'};

/* ---------- state ---------- */
let x = Math.max(20, Math.random()*(innerWidth-W)), dir = 1, state='intro', frame=0, dinolast=0, askTimer, dismiss;
const SPEED = 70; // px / second
const place = ()=>{ pet.style.left=x+'px'; flip.style.transform = dir<0?'scaleX(-1)':'none'; };

/* ---------- 1. fall → 2. dizzy wake-up → 3. nod → 4. walk ---------- */
async function intro(){
  place();
  pet.style.transition='none';
  pet.style.transform=`translateY(${-(innerHeight+250)}px)`;
  show('fall','fall');
  pet.offsetHeight;                                            // reflow
  pet.style.transition='transform 1.2s cubic-bezier(.55,.05,.9,.45)';
  pet.style.transform='translateY(0)';
  await sleep(1250);
//   show('lying','lying squash');       await sleep(1500);       // ouch, lying on the ground
  show('dizzy','wobble');             await sleep(2800);       // wakes up, dizzy
  show('nod','nod');                  await sleep(1900);       // shakes it off, nods
  show('stand');                      await sleep(600);
  startWalking();
}

/* ---------- walking along the bottom ---------- */
function startWalking(){
  state='walk'; show('walkA','walk');
  clearInterval(askTimer);
  askTimer=setInterval(()=>{ if(state==='walk') askToPlay(); },15000);   // every 15 s
  dinolast=performance.now(); requestAnimationFrame(loop);
}
function loop(t){
  if(state!=='walk') return;
  const dt=(t-dinolast)/1000; dinolast=t;
  x+=dir*SPEED*dt;
  if(x<0){x=0;dir=1} if(x>innerWidth-W){x=innerWidth-W;dir=-1}
  place(); requestAnimationFrame(loop);
}
setInterval(()=>{ if(state==='walk'){ frame^=1; show(frame?'walkB':'walkA','walk'); } },220);

